  4045          cp = out = xmalloc(strlen(s) + 1);
  4046          for (; *s != '\0'; s++) {
  4047                  if (*s == '#' && s[1] == '{')
  4048                          brackets++;
  4049                  if (brackets == 0 &&
  4050                      *s == '#' &&
  4051                      strchr(",#{}:", s[1]) != NULL) {
  4052                          *cp++ = *++s;
  4053                          continue;
  4054                  }
  4055                  if (*s == '}')
  4056                          brackets--;
  4057                  *cp++ = *s;
