  4183  /* Build modifier list. */
  4184  static struct format_modifier *
  4185  format_build_modifiers(struct format_expand_state *es, const char **s,
  4186      u_int *count)
  4187  {
  4188          const char              *cp = *s, *end;
  4189          struct format_modifier  *list = NULL;
  4190          char                     c, last[] = "X;:", **argv, *value;
  4191          int                      argc;
  4192
  4193          /*
  4194           * Modifiers are a ; separated list of the forms:
  4195           *      l,m,C,a,b,c,d,n,t,w,q,E,T,S,W,P,R,<,>
  4196           *      =a
  4197           *      =/a
  4198           *      =/a/
  4199           *      s/a/b/
  4200           *      s/a/b
  4201           *      ||,&&,!=,==,<=,>=
  4202           */
  4203
  4204          *count = 0;
  4205
  4206          while (*cp != '\0' && *cp != ':') {
  4207                  /* Skip any separator character. */
  4208                  if (*cp == ';')
  4209                          cp++;
  4210
  4211                  /* Check single character modifiers with no arguments. */
  4212                  if (strchr("labcdnwETSWPL!<>", cp[0]) != NULL &&
  4213                      format_is_end(cp[1])) {
  4214                          format_add_modifier(&list, count, cp, 1, NULL, 0);
  4215                          cp++;
  4216                          continue;
  4217                  }
  4218
  4219                  /* Then try double character with no arguments. */
  4220                  if ((memcmp("||", cp, 2) == 0 ||
  4221                      memcmp("&&", cp, 2) == 0 ||
  4222                      memcmp("!!", cp, 2) == 0 ||
  4223                      memcmp("!=", cp, 2) == 0 ||
  4224                      memcmp("==", cp, 2) == 0 ||
  4225                      memcmp("<=", cp, 2) == 0 ||
  4226                      memcmp(">=", cp, 2) == 0) &&
  4227                      format_is_end(cp[2])) {
  4228                          format_add_modifier(&list, count, cp, 2, NULL, 0);
  4229                          cp += 2;
  4230                          continue;
  4231                  }
  4232
  4233                  /* Now try single character with arguments. */
  4234                  if (strchr("mCLNPSst=pReqW", cp[0]) == NULL)
  4235                          break;
  4236                  c = cp[0];
  4237
  4238                  /* No arguments provided. */
  4239                  if (format_is_end(cp[1])) {
  4240                          format_add_modifier(&list, count, cp, 1, NULL, 0);
  4241                          cp++;
  4242                          continue;
  4243                  }
  4244                  argv = NULL;
  4245                  argc = 0;
  4246
  4247                  /* Single argument with no wrapper character. */
  4248                  if (!ispunct((u_char)cp[1]) || cp[1] == '-') {
  4249                          end = format_skip(cp + 1, ":;");
  4250                          if (end == NULL)
  4251                                  break;
  4252
  4253                          argv = xcalloc(1, sizeof *argv);
  4254                          value = xstrndup(cp + 1, end - (cp + 1));
  4255                          argv[0] = format_expand1(es, value);
  4256                          free(value);
  4257                          argc = 1;
  4258
  4259                          format_add_modifier(&list, count, &c, 1, argv, argc);
  4260                          cp = end;
  4261                          continue;
  4262                  }
  4263
  4264                  /* Multiple arguments with a wrapper character. */
  4265                  last[0] = cp[1];
  4266                  cp++;
  4267                  do {
  4268                          if (cp[0] == last[0] && format_is_end(cp[1])) {
  4269                                  cp++;
  4270                                  break;
  4271                          }
  4272                          end = format_skip(cp + 1, last);
  4273                          if (end == NULL)
  4274                                  break;
  4275                          cp++;
  4276
  4277                          argv = xreallocarray(argv, argc + 1, sizeof *argv);
  4278                          value = xstrndup(cp, end - cp);
  4279                          argv[argc++] = format_expand1(es, value);
  4280                          free(value);
  4281
  4282                          cp = end;
  4283                  } while (!format_is_end(cp[0]));
  4284                  format_add_modifier(&list, count, &c, 1, argv, argc);
  4285          }
  4286          if (*cp != ':') {
  4287                  format_free_modifiers(list, *count);
  4288                  *count = 0;
  4289                  return (NULL);
  4290          }
  4291          *s = cp + 1;
  4292          return (list);
  4293  }
