  4374  /* Handle n-ary boolean operators, "&&" and "||". */
  4375  static char *
  4376  format_bool_op_n(struct format_expand_state *es, const char *fmt, int and)
  4377  {
  4378          int              result;
  4379          const char      *cp1, *cp2;
  4380          char            *raw, *expanded;
  4381
  4382          result = and ? 1 : 0;
  4383          cp1 = fmt;
  4384
  4385          while (and ? result : !result) {
  4386                  cp2 = format_skip(cp1, ",");
  4387
  4388                  if (cp2 == NULL)
  4389                          raw = xstrdup(cp1);
  4390                  else
  4391                          raw = xstrndup(cp1, cp2 - cp1);
  4392                  expanded = format_expand1(es, raw);
  4393                  free(raw);
  4394                  format_log(es, "operator %s has operand: %s",
  4395                      and ? "&&" : "||", expanded);
  4396
  4397                  if (and)
  4398                          result = result && format_true(expanded);
  4399                  else
  4400                          result = result || format_true(expanded);
  4401                  free(expanded);
  4402
  4403                  if (cp2 == NULL)
  4404                          break;
  4405                  else
  4406                          cp1 = cp2 + 1;
  4407          }
  4408
  4409          return (xstrdup(result ? "1" : "0"));
  4410  }
