  4710
  4711  static char *
  4712  format_replace_expression(struct format_modifier *mexp,
  4713      struct format_expand_state *es, const char *copy)
  4714  {
  4715          int                      argc = mexp->argc;
  4716          const char              *errstr;
  4717          char                    *endch, *value, *left = NULL, *right = NULL;
  4718          int                      use_fp = 0;
  4719          u_int                    prec = 0;
  4720          double                   mleft, mright, result;
  4721          enum { ADD,
  4722                 SUBTRACT,
  4723                 MULTIPLY,
  4724                 DIVIDE,
  4725                 MODULUS,
  4726                 EQUAL,
  4727                 NOT_EQUAL,
  4728                 GREATER_THAN,
  4729                 GREATER_THAN_EQUAL,
  4730                 LESS_THAN,
  4731                 LESS_THAN_EQUAL } operator;
  4732
  4733          if (strcmp(mexp->argv[0], "+") == 0)
  4734                  operator = ADD;
  4735          else if (strcmp(mexp->argv[0], "-") == 0)
  4736                  operator = SUBTRACT;
  4737          else if (strcmp(mexp->argv[0], "*") == 0)
  4738                  operator = MULTIPLY;
  4739          else if (strcmp(mexp->argv[0], "/") == 0)
  4740                  operator = DIVIDE;
  4741          else if (strcmp(mexp->argv[0], "%") == 0 ||
  4742              strcmp(mexp->argv[0], "m") == 0)
  4743                  operator = MODULUS;
  4744          else if (strcmp(mexp->argv[0], "==") == 0)
  4745                  operator = EQUAL;
  4746          else if (strcmp(mexp->argv[0], "!=") == 0)
  4747                  operator = NOT_EQUAL;
  4748          else if (strcmp(mexp->argv[0], ">") == 0)
  4749                  operator = GREATER_THAN;
  4750          else if (strcmp(mexp->argv[0], "<") == 0)
  4751                  operator = LESS_THAN;
  4752          else if (strcmp(mexp->argv[0], ">=") == 0)
  4753                  operator = GREATER_THAN_EQUAL;
  4754          else if (strcmp(mexp->argv[0], "<=") == 0)
  4755                  operator = LESS_THAN_EQUAL;
  4756          else {
  4757                  format_log(es, "expression has no valid operator: '%s'",
  4758                      mexp->argv[0]);
  4759                  goto fail;
  4760          }
  4761
  4762          /* The second argument may be flags. */
  4763          if (argc >= 2 && strchr(mexp->argv[1], 'f') != NULL) {
  4764                  use_fp = 1;
  4765                  prec = 2;
  4766          }
  4767
  4768          /* The third argument may be precision. */
  4769          if (argc >= 3) {
  4770                  prec = strtonum(mexp->argv[2], INT_MIN, INT_MAX, &errstr);
  4771                  if (errstr != NULL) {
  4772                          format_log(es, "expression precision %s: %s", errstr,
  4773                              mexp->argv[2]);
  4774                          goto fail;
  4775                  }
  4776          }
  4777
  4778          if (format_choose(es, copy, &left, &right, 1) != 0) {
  4779                  format_log(es, "expression syntax error");
  4780                  goto fail;
  4781          }
  4782
  4783          mleft = strtod(left, &endch);
  4784          if (*endch != '\0') {
  4785                  format_log(es, "expression left side is invalid: %s", left);
  4786                  goto fail;
  4787          }
  4788
  4789          mright = strtod(right, &endch);
  4790          if (*endch != '\0') {
  4791                  format_log(es, "expression right side is invalid: %s", right);
  4792                  goto fail;
  4793          }
  4794
  4795          if (!use_fp) {
  4796                  mleft = (long long)mleft;
  4797                  mright = (long long)mright;
  4798          }
  4799          format_log(es, "expression left side is: %.*f", prec, mleft);
  4800          format_log(es, "expression right side is: %.*f", prec, mright);
  4801
  4802          switch (operator) {
  4803          case ADD:
  4804                  result = mleft + mright;
  4805                  break;
  4806          case SUBTRACT:
  4807                  result = mleft - mright;
  4808                  break;
  4809          case MULTIPLY:
  4810                  result = mleft * mright;
  4811                  break;
  4812          case DIVIDE:
  4813                  result = mleft / mright;
  4814                  break;
  4815          case MODULUS:
  4816                  result = fmod(mleft, mright);
  4817                  break;
  4818          case EQUAL:
  4819                  result = fabs(mleft - mright) < 1e-9;
  4820                  break;
  4821          case NOT_EQUAL:
  4822                  result = fabs(mleft - mright) > 1e-9;
  4823                  break;
  4824          case GREATER_THAN:
  4825                  result = (mleft > mright);
  4826                  break;
  4827          case GREATER_THAN_EQUAL:
  4828                  result = (mleft >= mright);
  4829                  break;
  4830          case LESS_THAN:
  4831                  result = (mleft < mright);
  4832                  break;
  4833          case LESS_THAN_EQUAL:
  4834                  result = (mleft <= mright);
  4835                  break;
  4836          }
  4837          if (use_fp)
  4838                  xasprintf(&value, "%.*f", prec, result);
  4839          else
  4840                  xasprintf(&value, "%.*f", prec, (double)(long long)result);
  4841          format_log(es, "expression result is %s", value);
  4842
  4843          free(right);
  4844          free(left);
  4845          return (value);
  4846
  4847  fail:
  4848          free(right);
  4849          free(left);
  4850          return (NULL);
  4851  }
