  4853  /* Replace a key. */
  4854  static int
  4855  format_replace(struct format_expand_state *es, const char *key, size_t keylen,
  4856      char **buf, size_t *len, size_t *off)
  4857  {
  4858          struct sort_criteria             *sc = &sort_crit;
  4859          struct format_tree               *ft = es->ft;
  4860          struct window_pane               *wp = ft->wp;
  4861          const char                       *errstr, *copy, *cp, *cp2;
  4862          const char                       *marker = NULL;
  4863          char                             *time_format = NULL;
  4864          char                             *copy0, *condition, *found, *new;
  4865          char                             *value, *left, *right;
  4866          size_t                            valuelen;
  4867          int                               modifiers = 0, limit = 0, width = 0;
  4868          int                               j, c;
  4869          struct format_modifier           *list, *cmp = NULL, *search = NULL;
  4870          struct format_modifier          **sub = NULL, *mexp = NULL, *fm;
  4871          struct format_modifier           *bool_op_n = NULL;
  4872          u_int                             i, count, nsub = 0, nrep;
  4873          struct format_expand_state        next;
  4874
  4875          /* Set sorting defaults. */
  4876          sc->order = SORT_ORDER;
  4877          sc->reversed = 0;
  4878
  4879          /* Make a copy of the key. */
  4880          copy = copy0 = xstrndup(key, keylen);
  4881
  4882          /* Process modifier list. */
  4883          list = format_build_modifiers(es, &copy, &count);
  4884          for (i = 0; i < count; i++) {
  4885                  fm = &list[i];
  4886                  if (format_logging(ft)) {
  4887                          format_log(es, "modifier %u is %s", i, fm->modifier);
  4888                          for (j = 0; j < fm->argc; j++) {
  4889                                  format_log(es, "modifier %u argument %d: %s", i,
  4890                                      j, fm->argv[j]);
  4891                          }
  4892                  }
  4893                  if (fm->size == 1) {
  4894                          switch (fm->modifier[0]) {
  4895                          case 'm':
  4896                          case '<':
  4897                          case '>':
  4898                                  cmp = fm;
  4899                                  break;
  4900                          case '!':
  4901                                  modifiers |= FORMAT_NOT;
  4902                                  break;
  4903                          case 'C':
  4904                                  search = fm;
  4905                                  break;
  4906                          case 's':
  4907                                  if (fm->argc < 2)
  4908                                          break;
  4909                                  sub = xreallocarray(sub, nsub + 1, sizeof *sub);
  4910                                  sub[nsub++] = fm;
  4911                                  break;
  4912                          case '=':
  4913                                  if (fm->argc < 1)
  4914                                          break;
  4915                                  limit = strtonum(fm->argv[0], INT_MIN, INT_MAX,
  4916                                      &errstr);
  4917                                  if (errstr != NULL)
  4918                                          limit = 0;
  4919                                  if (fm->argc >= 2 && fm->argv[1] != NULL)
  4920                                          marker = fm->argv[1];
  4921                                  break;
  4922                          case 'p':
  4923                                  if (fm->argc < 1)
  4924                                          break;
  4925                                  width = strtonum(fm->argv[0], INT_MIN, INT_MAX,
  4926                                      &errstr);
  4927                                  if (errstr != NULL)
  4928                                          width = 0;
  4929                                  break;
  4930                          case 'w':
  4931                                  modifiers |= FORMAT_WIDTH;
  4932                                  break;
  4933                          case 'e':
  4934                                  if (fm->argc < 1 || fm->argc > 3)
  4935                                          break;
  4936                                  mexp = fm;
  4937                                  break;
  4938                          case 'l':
  4939                                  modifiers |= FORMAT_LITERAL;
  4940                                  break;
  4941                          case 'a':
  4942                                  modifiers |= FORMAT_CHARACTER;
  4943                                  break;
  4944                          case 'b':
  4945                                  modifiers |= FORMAT_BASENAME;
  4946                                  break;
  4947                          case 'c':
  4948                                  modifiers |= FORMAT_COLOUR;
  4949                                  break;
  4950                          case 'd':
  4951                                  modifiers |= FORMAT_DIRNAME;
  4952                                  break;
  4953                          case 'n':
  4954                                  modifiers |= FORMAT_LENGTH;
  4955                                  break;
  4956                          case 't':
  4957                                  modifiers |= FORMAT_TIMESTRING;
  4958                                  if (fm->argc < 1)
  4959                                          break;
  4960                                  if (strchr(fm->argv[0], 'p') != NULL)
  4961                                          modifiers |= FORMAT_PRETTY;
  4962                                  else if (fm->argc >= 2 &&
  4963                                      strchr(fm->argv[0], 'f') != NULL)
  4964                                          time_format = format_strip(fm->argv[1]);
  4965                                  break;
  4966                          case 'q':
  4967                                  if (fm->argc < 1)
  4968                                          modifiers |= FORMAT_QUOTE_SHELL;
  4969                                  else if (strchr(fm->argv[0], 'e') != NULL ||
  4970                                      strchr(fm->argv[0], 'h') != NULL)
  4971                                          modifiers |= FORMAT_QUOTE_STYLE;
  4972                                  break;
  4973                          case 'E':
  4974                                  modifiers |= FORMAT_EXPAND;
  4975                                  break;
  4976                          case 'T':
  4977                                  modifiers |= FORMAT_EXPANDTIME;
  4978                                  break;
  4979                          case 'N':
