  4981                                      strchr(fm->argv[0], 'w') != NULL)
  4982                                          modifiers |= FORMAT_WINDOW_NAME;
  4983                                  else if (strchr(fm->argv[0], 's') != NULL)
  4984                                          modifiers |= FORMAT_SESSION_NAME;
  4985                                  break;
  4986                          case 'S':
  4987                                  modifiers |= FORMAT_SESSIONS;
  4988                                  if (fm->argc < 1) {
  4989                                          sc->order= SORT_INDEX;
  4990                                          sc->reversed = 0;
  4991                                          break;
  4992                                  }
  4993                                  if (strchr(fm->argv[0], 'i') != NULL)
  4994                                          sc->order = SORT_INDEX;
  4995                                  else if (strchr(fm->argv[0], 'n') != NULL)
  4996                                          sc->order = SORT_NAME;
  4997                                  else if (strchr(fm->argv[0], 't') != NULL)
  4998                                          sc->order = SORT_ACTIVITY;
  4999                                  else
  5000                                          sc->order = SORT_INDEX;
  5001                                  if (strchr(fm->argv[0], 'r') != NULL)
  5002                                          sc->reversed = 1;
  5003                                  else
  5004                                          sc->reversed = 0;
  5005                                  break;
  5006                          case 'W':
  5007                                  modifiers |= FORMAT_WINDOWS;
  5008                                  if (fm->argc < 1) {
  5009                                          sc->order = SORT_ORDER;
  5010                                          sc->reversed = 0;
  5011                                          break;
  5012                                  }
  5013                                  if (strchr(fm->argv[0], 'i') != NULL)
  5014                                          sc->order = SORT_ORDER;
  5015                                  else if (strchr(fm->argv[0], 'n') != NULL)
  5016                                          sc->order = SORT_NAME;
  5017                                  else if (strchr(fm->argv[0], 't') != NULL)
  5018                                          sc->order = SORT_ACTIVITY;
  5019                                  else
  5020                                          sc->order = SORT_ORDER;
  5021                                  if (strchr(fm->argv[0], 'r') != NULL)
  5022                                          sc->reversed = 1;
  5023                                  else
  5024                                          sc->reversed = 0;
  5025                                  break;
  5026                          case 'P':
  5027                                  modifiers |= FORMAT_PANES;
  5028                                  sc->order = SORT_CREATION;
  5029                                  if (fm->argc < 1) {
  5030                                          sc->reversed = 0;
  5031                                          break;
  5032                                  }
  5033                                  if (strchr(fm->argv[0], 'r') != NULL)
  5034                                          sc->reversed = 1;
  5035                                  else
  5036                                          sc->reversed = 0;
  5037                                  break;
  5038                          case 'L':
  5039                                  modifiers |= FORMAT_CLIENTS;
  5040                                  if (fm->argc < 1) {
  5041                                          sc->order = SORT_ORDER;
  5042                                          sc->reversed = 0;
  5043                                          break;
  5044                                  }
  5045                                  if (strchr(fm->argv[0], 'i') != NULL)
  5046                                          sc->order = SORT_ORDER;
  5047                                  else if (strchr(fm->argv[0], 'n') != NULL)
  5048                                          sc->order = SORT_NAME;
  5049                                  else if (strchr(fm->argv[0], 't') != NULL)
  5050                                          sc->order = SORT_ACTIVITY;
  5051                                  else
  5052                                          sc->order = SORT_ORDER;
  5053                                  if (strchr(fm->argv[0], 'r') != NULL)
  5054                                          sc->reversed = 1;
  5055                                  else
  5056                                          sc->reversed = 0;
  5057                                  break;
  5058                          case 'R':
  5059                                  modifiers |= FORMAT_REPEAT;
  5060                                  break;
  5061                          }
  5062                  } else if (fm->size == 2) {
  5063                          if (strcmp(fm->modifier, "||") == 0 ||
  5064                              strcmp(fm->modifier, "&&") == 0)
  5065                                  bool_op_n = fm;
  5066                          else if (strcmp(fm->modifier, "!!") == 0)
  5067                                  modifiers |= FORMAT_NOT_NOT;
  5068                          else if (strcmp(fm->modifier, "==") == 0 ||
  5069                              strcmp(fm->modifier, "!=") == 0 ||
  5070                              strcmp(fm->modifier, ">=") == 0 ||
  5071                              strcmp(fm->modifier, "<=") == 0)
  5072                                  cmp = fm;
