  5107          /* Is this a loop, operator, comparison or condition? */
  5108          if (modifiers & FORMAT_SESSIONS) {
  5109                  value = format_loop_sessions(es, copy);
  5110                  if (value == NULL)
  5111                          goto fail;
  5112          } else if (modifiers & FORMAT_WINDOWS) {
  5113                  value = format_loop_windows(es, copy);
  5114                  if (value == NULL)
  5115                          goto fail;
  5116          } else if (modifiers & FORMAT_PANES) {
  5117                  value = format_loop_panes(es, copy);
  5118                  if (value == NULL)
  5119                          goto fail;
  5120          } else if (modifiers & FORMAT_CLIENTS) {
  5121                  value = format_loop_clients(es, copy);
  5122                  if (value == NULL)
  5123                          goto fail;
  5124          } else if (modifiers & FORMAT_WINDOW_NAME) {
  5125                  value = format_window_name(es, copy);
  5126                  if (value == NULL)
  5127                          goto fail;
  5128          } else if (modifiers & FORMAT_SESSION_NAME) {
  5129                  value = format_session_name(es, copy);
  5130                  if (value == NULL)
  5131                          goto fail;
  5132          } else if (search != NULL) {
