  5138                  } else {
  5139                          format_log(es, "search '%s' pane %%%u", new, wp->id);
  5140                          value = format_search(search, wp, new);
  5141                  }
  5142                  free(new);
  5143      } else if (modifiers & FORMAT_REPEAT) {
