  5157                                  value = new;
  5158                          }
  5159                  }
  5160                  free(right);
  5161                  free(left);
  5162      } else if (modifiers & FORMAT_NOT) {
  5163                  value = format_bool_op_1(es, copy, 1);
  5164          } else if (modifiers & FORMAT_NOT_NOT) {
  5165                  value = format_bool_op_1(es, copy, 0);
  5166          } else if (bool_op_n != NULL) {
  5167                  /* n-ary boolean operator. */
  5168                  if (strcmp(bool_op_n->modifier, "||") == 0)
  5169                          value = format_bool_op_n(es, copy, 0);
  5170                  else if (strcmp(bool_op_n->modifier, "&&") == 0)
  5171                          value = format_bool_op_n(es, copy, 1);
  5172          } else if (cmp != NULL) {
  5173                  /* Comparison of left and right. */
  5174                  if (format_choose(es, copy, &left, &right, 1) != 0) {
  5175                          format_log(es, "compare %s syntax error: %s",
  5176                              cmp->modifier, copy);
  5177                          goto fail;
  5178                  }
  5179                  format_log(es, "compare %s left is: %s", cmp->modifier, left);
